        <span
          key={label.id}
          className={cn(
            'absolute top-0 text-[11px] whitespace-nowrap tabular-nums',
            strongOf(label.isStrong)
          )}
          style={labelStyleOf(label, align)}
        >
          {label.text}
        </span>
      ))}
    </div>
  );
}

